# Generated by `shiny theme new` from shiny-creation.png
# Base scheme: Catppuccin Mocha — https://github.com/mbadolato/iTerm2-Color-Schemes (via Ghostty)
# Edit freely; `shiny theme set <name>` re-applies.
THEME_BASE="Catppuccin Mocha"
GHOSTTY_THEME="Catppuccin Mocha"   # built-in: ghostty +list-themes
ACCENT_PRESET=5                    # macOS accent: -1 graphite 0 red 1 orange 2 yellow 3 green 4 blue 5 purple 6 pink
WALLPAPER="wallpaper.jpg"

BG="#1E1E2E"         # window background
BG_DARK="#181825"    # frames, omnibox
SURFACE="#313244"    # borders, dividers, inactive window border
SELECTION="#45475A"  # selected rows, text selection
MUTED="#585B70"      # shortcuts, scrollbar
COMMENT="#7F849C"    # subtext, inactive tabs
FG="#CDD6F4"         # primary text
FG_DIM="#BAC2DE"     # secondary text
ACCENT="#CBA6F7"     # primary accent: focus border, icons, links, text highlight, icon tint
ACCENT2="#B4BEFE"    # secondary accent: cursor, shortcuts, search selection
